<div class="v5-section v5-card"><div class="v5-section-head"><div><h2>Histórico de E-mails</h2><small style="color:var(--v5-muted)">Destinatário, assunto, status, provedor e operador.</small></div></div><div style="overflow:auto"><table class="v5-table"><thead><tr><th>Data</th><th>Destinatário</th><th>Assunto</th><th>Status</th><th>Operador</th><th>Erro</th></tr></thead><tbody id="mailRows"><tr><td colspan="6" style="color:var(--v5-muted)">Carregando…</td></tr></tbody></table></div></div>
@push('scripts')<script>fetch('/communication-logs/emails?limit=100',{headers:{Accept:'application/json'},credentials:'same-origin'}).then(r=>r.json()).then(d=>{document.getElementById('mailTotal').textContent=d.stats?.total??0;document.getElementById('mailSent').textContent=d.stats?.sent??0;document.getElementById('mailFailed').textContent=d.stats?.failed??0;document.getElementById('mailRows').innerHTML=(d.items||[]).map(x=>`<tr><td>${x.sent_at||x.created_at||'-'}</td><td>${x.recipient||'-'}</td><td>${x.subject||'-'}</td><td><span class="v5-badge">${x.status||'-'}</span></td><td>${x.operator||x.operator_name||'-'}</td><td>${x.error_message||x.error||''}</td></tr>`).join('')||'<tr><td colspan="6">Nenhum e-mail registrado.</td></tr>'}).catch(()=>document.getElementById('mailRows').innerHTML='<tr><td colspan="6">Falha ao carregar histórico.</td></tr>');</script>@endpush
